"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[36542],{7426:e=>{e.exports=JSON.parse('{"functions":[{"name":"SetCombat","desc":"Turn the server-wide Combat context on or off (e.g. a pirate attack).","params":[{"name":"on","desc":"","lua_type":"boolean"}],"returns":[],"function_type":"static","source":{"line":103,"path":"src/ServerStorage/SharedModules/MusicService.luau"}},{"name":"Initialize","desc":"Start the context poll. Call exactly once from the owning server script.","params":[],"returns":[],"function_type":"static","source":{"line":111,"path":"src/ServerStorage/SharedModules/MusicService.luau"}}],"properties":[],"types":[],"name":"MusicService","desc":"Server BGM orchestrator: every player hears the same song at the same moment.\\nIt resolves one music context for the whole server by priority\\nJump > Boss > Combat > Pursuit > LowFuel > Normal, runs that playlist (shuffle\\norder, gaps, crossfade lead), and publishes the current track as the\\n`workspace.Bgm` attribute: `\\"<context>|<assetId>|<serverStartTime>\\"`\\n(assetId \\"\\" = silence). Clients play that track from\\n`GetServerTimeNow() - serverStartTime`, so late joiners land in sync.\\nCombat comes from `SetCombat`; the other inputs are polled from their managers.","realm":["Server"],"source":{"line":15,"path":"src/ServerStorage/SharedModules/MusicService.luau"}}')}}]);